import type { Html } from "foldkit/html";
import { html } from "foldkit/html";

import { directionButtonClassName, directionRootClassName } from "./view";

export {
  directionButtonClassName,
  directionCardClassName,
  directionControlsClassName,
  directionPreviewClassName,
  directionRootClassName,
} from "./view";

/** Text direction values supported by the direction provider helper. */
export type Direction = "ltr" | "rtl";

/** Config for wrapping content in an inherited direction context. */
export type DirectionViewConfig = Readonly<{
  direction: Direction;
  children: readonly (Html | string)[];
  className?: string;
}>;

/** Config for a direction toggle button. */
export type DirectionButtonViewConfig<ParentMessage> = Readonly<{
  direction: Direction;
  currentDirection: Direction;
  label: string;
  onClick: ParentMessage;
  className?: string;
}>;

const classNames = (base: string, className?: string): string =>
  [base, className]
    .filter((value): value is string => value !== undefined && value !== "")
    .join(" ");

/** Wraps children with `dir`, mirroring shadcn's DirectionProvider in Foldkit form. */
export const view = <ParentMessage>({
  direction,
  children,
  className,
}: DirectionViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.Dir(direction),
      h.DataAttribute("slot", "direction"),
      h.DataAttribute("direction", direction),
      h.Class(classNames(directionRootClassName, className)),
    ],
    children
  );
};

/** Renders a native button for parent-owned direction switching. */
export const buttonView = <ParentMessage>({
  direction,
  currentDirection,
  label,
  onClick,
  className,
}: DirectionButtonViewConfig<ParentMessage>): Html => {
  const h = html<ParentMessage>();

  return h.button(
    [
      h.Type("button"),
      h.AriaLabel(label),
      h.OnClick(onClick),
      h.DataAttribute(
        "active",
        currentDirection === direction ? "true" : "false"
      ),
      h.Class(classNames(directionButtonClassName, className)),
    ],
    [direction.toUpperCase()]
  );
};

export const directionRootClassName = "w-full";
export const directionPreviewClassName =
  "grid gap-4 rounded-lg border border-gray-200 bg-white p-6 text-gray-950 shadow-sm";
export const directionCardClassName =
  "space-y-3 rounded-md border border-gray-200 bg-gray-50 p-4";
export const directionControlsClassName = "flex flex-wrap items-center gap-2";
export const directionButtonClassName =
  "inline-flex h-9 items-center rounded-md border border-gray-300 bg-white px-3 text-sm font-medium text-gray-950 shadow-sm transition hover:bg-gray-50 focus:outline-none focus-visible:ring-2 focus-visible:ring-accent-600 data-[active=true]:border-accent-600 data-[active=true]:bg-accent-50 data-[active=true]:text-accent-700";

import { Scene } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";
import { describe, test } from "vitest";

import * as Direction from "./index";

describe("Direction registry view", () => {
  test("renders children under a dir attribute", () => {
    const view = (): Html => {
      const h = html<never>();

      return Direction.view<never>({
        direction: "rtl",
        children: [h.p([], ["مرحبا"])],
      });
    };

    Scene.scene(
      {
        update: (model: undefined): readonly [undefined, []] => [model, []],
        view,
      },
      Scene.with(undefined),
      Scene.expect(Scene.text("مرحبا")).toExist()
    );
  });
});
